    # Return a dict with keys new, applied, rejected, other in that order
    # Count jobs by job["status"]. Missing, None or unknown status counts as other.
    # Status matching ignores case and surrounding spaces.
    result = {
        'new': 0,
        'applied': 0,
        'rejected': 0,
        'other': 0,
    }
    for job in jobs:
        status = job.get('status')
        if status is None:
            result['other'] += 1
            continue
        # Only strings are processed, otherwise count as other
        if isinstance(status, str):
            cleaned = status.strip().lower()
            if cleaned == 'new':
                result['new'] += 1
            elif cleaned == 'applied':
                result['applied'] += 1
            elif cleaned == 'rejected':
                result['rejected'] += 1
            else:
                result['other'] += 1
        else:
            result['other'] += 1
    return result
